  "observations": [
    {
      "quote": "see an exception for married names in 8 FAM 403.1-4(C)",
      "rationale": "The parenthetical reference notes an exception for married names to the requirement that material discrepancies be documented with specified records, but the substantive terms of the exception are set forth in remote section 8 FAM 403.1-4(C). The qualification and remote citation are already represented in claim C0023.",
      "disposition": "already_represented"
    },
    {
      "quote": "The court order or decree must be final:",
      "rationale": "The requirement that a submitted court order or decree must be final serves as a governing lead-in to subsequent rules regarding pending name changes. It is already established as a requirement in C0010 and captured in the scope conditions of the relevant dependent provisions.",
      "disposition": "already_represented"
    },
    {
      "quote": "see 8 FAM 403.1-6 regarding “known as” names",
      "rationale": "The cross-reference to 8 FAM 403.1-6 clarifies the prohibition against continuing to use a previous name after a material name change and is already represented in the citations of baseline prohibition C0003.",
      "disposition": "already_represented"
    }
  ]
}
